const entrada = $('When Executed by Another Workflow').first().json;
let guardado = $input.first().json.estado;

// Redis devuelve texto, hay que convertirlo a objeto
if (typeof guardado === 'string') {
  try { guardado = JSON.parse(guardado); } catch (e) { guardado = null; }
}

const esNuevo = !guardado;
const estado = guardado || {
  paso: 'inicio',
  saludado: false,
  intentos: 0,
  historial: [],
  actualizado: new Date().toISOString()
};

return [{
  json: {
    telefono: entrada.telefono,
    mensaje: entrada.mensaje,
    esNuevo,
    estado
  }
}];

