const resp = $input.first().json;
const prev = $('Prompt del sistema').first().json;

const texto = (resp.candidates?.[0]?.content?.parts?.[0]?.text || '').trim();
const derivar = texto === '' || texto.includes('DERIVAR_HUMANO');

const estado = { ...prev.estado };
estado.historial = [
  ...(estado.historial || []),
  { rol: 'usuario', texto: prev.mensaje },
  { rol: 'bot', texto }
].slice(-10);

if (!derivar) {
  estado.saludado = true;
  if (estado.paso === 'inicio') estado.paso = 'menu';
}
estado.actualizado = new Date().toISOString();

return [{
  json: {
    telefono: prev.telefono,
    mensaje: prev.mensaje,
    respuesta: derivar ? null : texto,
    derivar,
    estado
  }
}];
